# -*- coding: utf-8 -*-
import threading
import time
import traceback

from elementum.dialog_select import DialogSelect
from elementum.logger import log


_lock = threading.RLock()
_pending_open = []
_installed = False
_original_show = None


def _queue_unique(queue, window):
    with _lock:
        if window not in queue:
            queue.append(window)


def _managed_show(window):
    if getattr(window, 'web_mode', False):
        return _original_show(window)

    with window.lock:
        window.remote_kodi_mode = False
        window.progressive_gui_managed = True
        window.progressive_gui_opened = False
        window.initialized = False
        window.finished = False
        window.web_updated_at = time.time()

    _queue_unique(_pending_open, window)
    log.info(
        'Progressive GUI modal open queued: session=%s items=%d'
        % (window.web_session_id, len(window.items))
    )
    return None


def install_progressive_gui_dispatcher():
    global _installed, _original_show

    with _lock:
        if _installed:
            return

        _original_show = DialogSelect.show
        DialogSelect.show = _managed_show
        _installed = True

    log.info('Progressive GUI modal dispatcher installed')


def _open_window_modal(window):
    with window.lock:
        if window.finished or window.progressive_gui_opened:
            return
        # Set this before doModal(). Provider callbacks can arrive while Kodi
        # is entering onInit(); DialogSelect.updateItems() stores the newest
        # items and onInit() then renders that latest snapshot.
        window.progressive_gui_opened = True

    try:
        log.info(
            'Progressive GUI doModal starting on service thread: session=%s items=%d thread=%s'
            % (
                window.web_session_id,
                len(window.items),
                threading.current_thread().name,
            )
        )

        # WindowXMLDialog.show() creates an empty shell on Kodi 21 without
        # dispatching onInit/onClick. A real doModal() must be entered from
        # the long-lived Elementum service Python thread. The RPC server and
        # provider callbacks keep running in their own threads and call the
        # original DialogSelect.updateItems() directly.
        super(DialogSelect, window).doModal()

        log.info(
            'Progressive GUI doModal finished: session=%s choice=%d items=%d'
            % (window.web_session_id, window.retval, len(window.items))
        )
    except Exception as exc:
        with window.lock:
            window.finished = True
        log.error(
            'Progressive GUI doModal failed: session=%s error=%s'
            % (window.web_session_id, repr(exc))
        )
        for line in traceback.format_exc().splitlines():
            log.error(line)
    finally:
        with window.lock:
            window.progressive_gui_opened = False


def process_pending_progressive_gui():
    # doModal() intentionally blocks this service-loop iteration until the
    # user selects or closes the dialog. Elementum's JSON-RPC server and the
    # daemon continue running in separate threads, so progressive updates are
    # still delivered to DialogSelect.updateItems() while the dialog is open.
    with _lock:
        if not _pending_open:
            return
        window = _pending_open.pop(0)

    _open_window_modal(window)
